import fs from "fs";
import path from "path";

/**
 * Server-side readers for the INFERRED review dataset.
 * Source: data/review/** — generated by scripts/build_ui_dataset.py from the
 * retained campaign dump (sha256 c06d8ab3…). This is a DERIVED read model,
 * NOT the canonical database. Canonical provisioning is a separate gated step.
 */

const DATA_DIR = path.join(process.cwd(), "data", "review");
/**
 * Canonical identity tables (read model). LIVES UNDER data/ (git-tracked and
 * Vercel-traced) — it used to point at download/read-model/tables, which the
 * .vercelignore excludes and the file tracer cannot see: the lifecycle
 * registry ENOENT-crashed every deployed /api/* route.
 */
const READ_MODEL_DIR =
  process.env.TV_READ_MODEL_DIR ||
  path.join(process.cwd(), "data", "read-model", "tables");
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export interface PaperSummary {
  id: string;
  title: string;
  paperCode: string;
  sessionLabel: string;
  bridgeStatus: "OK" | "REVIEW_REQUIRED" | string;
  questions: number;
  parts: number;
  schemes: number;
  points: number;
  findings: number;
}

export interface ReviewIndex {
  label: string;
  identity: { campaign: string; db: string; coreCommit: string };
  dumpSha256: string;
  stats: {
    papers: number; questions: number; versions: number; parts: number;
    schemes: number; points: number; embedded: number;
    suggestedVersions: number; validatedVersions: number;
    reviewRequiredSessions: number; okSessions: number;
  };
  quarantine: { session: string; rule: string };
  papers: PaperSummary[];
}

export interface SessionDossier {
  paper: {
    id: string; title: string; board: string; qualification: string;
    sessionLabel: string; paperCode: string; validationState: string;
    provenance: string; bridge: string;
  };
  bridge: {
    id: string; status: string; engine: string; bridge: string;
    findings: Array<Record<string, unknown>>;
  } | null;
  questionPaper: SourcePaper | null;
  markSchemePaper: SourcePaper | null;
  questions: QuestionItem[];
}

export interface SourcePaper {
  documentId: string; role: string; sourceUri: string;
  engine: string; engineVersion: string; checksum: string;
  chunkCount: number | string | null;
  chunks: Array<{ index: string; content: string }>;
}

export interface QuestionItem {
  id: string; externalRef: string; type: string; prompt: string;
  marks: number | string | null; commandWord: string | null;
  topicNode: string | null; versionId: string | null;
  validationState: string | null; origin: string | null;
  options: Array<{ label: string; text: string; isCorrect: boolean | string }>;
  parts: Array<{ id: string; label: string; text: string; partId: string }>;
  schemes: Array<{
    id: string; questionNumber: string; validationState: string;
    bridge: string;
    points: Array<{ id: string; partLabel: string; text: string; marks: string | number | null; partId: string | null }>;
  }>;
}

let indexCache: ReviewIndex | null = null;
const dossierCache = new Map<string, SessionDossier>();

export function getReviewIndex(): ReviewIndex {
  if (indexCache) return indexCache;
  const raw = fs.readFileSync(path.join(DATA_DIR, "index.json"), "utf-8");
  indexCache = JSON.parse(raw) as ReviewIndex;
  return indexCache;
}

export function getDossier(paperId: string): SessionDossier | null {
  if (!UUID_RE.test(paperId)) return null; // path-traversal guard
  const hit = dossierCache.get(paperId);
  if (hit) return hit;
  const file = path.join(DATA_DIR, "sessions", `${paperId}.json`);
  if (!fs.existsSync(file)) return null;
  const dossier = JSON.parse(fs.readFileSync(file, "utf-8")) as SessionDossier;
  dossierCache.set(paperId, dossier);
  return dossier;
}

/**
 * Target registry for lifecycle enforcement: every decidable row in the read
 * model with its CANONICAL lifecycle state (from the dump). The staged decision
 * log never mutates this — it stages teacher intent for the future gated apply.
 */
export interface LifecycleTarget {
  type: "question_version" | "mark_scheme" | "exam_paper";
  id: string;
  state: string;
  label: string;
  paperId: string | null;
}

let registryCache: Map<string, LifecycleTarget> | null = null;

function readJsonl(name: string): Array<Record<string, string>> {
  const file = path.join(READ_MODEL_DIR, `${name}.jsonl`);
  return fs.readFileSync(file, "utf-8").split("\n").filter(Boolean)
    .map((l) => JSON.parse(l) as Record<string, string>);
}

export function getLifecycleRegistry(): Map<string, LifecycleTarget> {
  if (registryCache) return registryCache;
  const reg = new Map<string, LifecycleTarget>();
  const papers = readJsonl("exam_papers");
  const paperTitle = new Map(papers.map((p) => [p.id, `${p.paper_code} · ${p.session_label}`]));
  for (const p of papers) {
    reg.set(p.id, { type: "exam_paper", id: p.id, state: p.validation_state, label: paperTitle.get(p.id) || p.title, paperId: p.id });
  }
  // question_id -> external_ref + exam_paper_id (for labels and paper linkage)
  const qInfo = new Map(
    readJsonl("questions").map((q) => [q.id, { ref: q.external_ref, paper: q.exam_paper_id || null }])
  );
  const verPaper = new Map<string, string | null>();
  for (const v of readJsonl("question_versions")) {
    const info = qInfo.get(v.question_id);
    const paperId = info?.paper || null;
    verPaper.set(v.id, paperId);
    const label = `${info?.ref || v.question_id} · v${v.version} · ${v.validation_state}`;
    reg.set(v.id, { type: "question_version", id: v.id, state: v.validation_state, label, paperId });
  }
  for (const s of readJsonl("mark_schemes")) {
    reg.set(s.id, {
      type: "mark_scheme", id: s.id, state: s.validation_state,
      label: `mark scheme #${s.question_number} (${paperTitle.get(verPaper.get(s.question_version_id) || "") || "linked via version"})`,
      paperId: verPaper.get(s.question_version_id) || null,
    });
  }
  registryCache = reg;
  return reg;
}
